rtl/apb_register.sv:
module apb_register(input wire PCLK, PRESETn, PSEL, PENABLE, PWRITE,
 input wire [15:0] PADDR, input wire [31:0] PWDATA,
 output wire [31:0] PRDATA, output wire PREADY, output wire PSLVERR);
 reg [31:0] mem [0:3];
 reg [1:0] wait_count;
 integer i;
 wire valid_addr = PADDR >= 16'h1000 && PADDR <= 16'h100c && PADDR[1:0] == 0;
 // Two access cycles of backpressure, followed by a ready cycle.
 assign PREADY = PSEL && PENABLE && wait_count == 2;
 assign PSLVERR = PREADY && !valid_addr;
 assign PRDATA = valid_addr ? mem[PADDR[3:2]] : 32'h0;
 always @(posedge PCLK or negedge PRESETn) begin
   if (!PRESETn) begin
     wait_count <= 0;
     for(i=0;i<4;i=i+1) mem[i] <= 0;
   end else if (!PSEL || !PENABLE) wait_count <= 0;
   else if (!PREADY) wait_count <= wait_count + 1'b1;
   else begin
     wait_count <= 0;
     if (PWRITE && !PSLVERR) mem[PADDR[3:2]] <= PWDATA;
   end
 end
endmodule

sim/tb_apb.sv:
`timescale 1ns/1ps
module tb_apb;
 reg PCLK=0, PRESETn=0, PSEL=0, PENABLE=0, PWRITE=0;
 reg [15:0] PADDR=0;
 reg [31:0] PWDATA=0;
 wire [31:0] PRDATA;
 wire PREADY, PSLVERR;
 integer waits=0;
 integer cycle=0, txid=0, observed_txid=0, errors=0;
 reg [31:0] expected[0:3];
 integer i;
 apb_register dut(.*);
 always #5 PCLK=~PCLK;
 // Each EV row is sampled from the real bus, not a canned animation.
 task emit(input [8*20-1:0] component, input [8*24-1:0] phase, input [8*64-1:0] message);
 begin
  $display("EV|%0d|%0d|%0s|%0s|%0h|%0h|%0h|%0d|%0d|%0d|%0d|%0d|%0s",cycle,txid,component,phase,PADDR,PWDATA,PRDATA,PSEL,PENABLE,PWRITE,PREADY,PSLVERR,message);
 end endtask
 // Independent passive monitor: only reads bus signals, never drives them.
 // Sample on posedge, before DUT nonblocking assignments update state.
 always @(posedge PCLK) begin
  if(PRESETn) begin
   cycle=cycle+1;
   if(PSEL && !PENABLE) begin waits=0; emit("monitor","SETUP","Observed setup phase"); end
   if(PSEL && PENABLE) begin
    if(!PREADY) begin waits=waits+1; emit("monitor","WAIT","ACCESS stalled PREADY=0"); end
    else begin
     if(waits != 2) begin errors=errors+1; emit("scoreboard","FAIL","Peripheral requires exactly two wait cycles"); end
     emit("dut","COMPLETE","Transfer accepted at rising edge");
     emit("monitor","HANDSHAKE","Observed transfer completion");
     // Independent address decode and response prediction.
     if (PSLVERR !== !(PADDR >= 16'h1000 && PADDR <= 16'h100c && PADDR[1:0]==0)) begin
       errors=errors+1;
       emit("scoreboard","FAIL","Unexpected PSLVERR response");
     end else if(PSLVERR) emit("scoreboard","EXPECTED_ERROR","PASS: expected slave error observed");
     else if(PWRITE) begin
       expected[PADDR[3:2]]=PWDATA;
       emit("scoreboard","UPDATE","Reference model updated from observed write");
     end else if(PRDATA === (expected[PADDR[3:2]] ^ ($test$plusargs("DVFLOW_INJECT_MISMATCH") ? 32'h1 : 32'h0))) emit("scoreboard","PASS","Read matches reference model");
     else begin
       errors=errors+1;
       emit("scoreboard","FAIL","Read mismatch: compare PRDATA against expected register value");
       $display("CHECK expected=%08h actual=%08h",expected[PADDR[3:2]],PRDATA);
     end
    end
   end
  end
 end
 task transfer(input bit wr, input [15:0] addr, input [31:0] data);
 integer guard;
 begin
  txid=txid+1;
  @(negedge PCLK);
  PADDR=addr; PWDATA=data; PWRITE=wr; PSEL=0; PENABLE=0;
  emit("sequence","ITEM","New sequence item");
  emit("sequencer","ITEM","Item granted to driver");
  emit("driver","ITEM","Driver accepted item");
  PSEL=1;
  emit("driver","SETUP","Driving APB setup");
  @(negedge PCLK);
  PENABLE=1;
  emit("driver","ACCESS","Driving APB access");
  guard=0;
  begin : wait_for_ready
   forever begin
    @(posedge PCLK);
    if(PREADY) disable wait_for_ready;
    guard=guard+1;
    if(guard>10) begin $display("TIMEOUT"); $fatal(1,"APB timeout"); end
   end
  end
  @(negedge PCLK);
  PSEL=0; PENABLE=0;
 end endtask
 initial begin
  for(i=0;i<4;i=i+1) expected[i]=0;
  repeat(2) @(negedge PCLK);
  PRESETn=1;
  begin : custom_sequence
   integer fd, rc, wr, addr, data;
   reg [1023:0] filename;
   if (!$value$plusargs("SEQ=%s", filename)) $fatal(1,"Missing sequence file");
   fd=$fopen(filename,"r"); if(!fd) $fatal(1,"Cannot open sequence");
   rc=$fscanf(fd,"%d %h %h",wr,addr,data);
   while(rc==3) begin
    transfer(wr,addr,data);
    rc=$fscanf(fd,"%d %h %h",wr,addr,data);
   end
   $fclose(fd);
  end
  if(errors) $fatal(1,"Scoreboard failures: %0d",errors);
  $display("DONE"); $finish;
 end
endmodule

