`timescale 1ns/1ps
module tb_uvm;
 import uvm_pkg::*;
 import apb_uvm_pkg::*;
 bit clk=0;
 always #5 clk=~clk;
 apb_if bus(clk);
 apb_register dut(.PCLK(clk),.PRESETn(bus.PRESETn),.PSEL(bus.PSEL),.PENABLE(bus.PENABLE),.PWRITE(bus.PWRITE),.PADDR(bus.PADDR),.PWDATA(bus.PWDATA),.PRDATA(bus.PRDATA),.PREADY(bus.PREADY),.PSLVERR(bus.PSLVERR));
 initial begin repeat(3) @(negedge clk);bus.PRESETn=1;end
 initial begin uvm_config_db#(virtual apb_if)::set(null,"*","vif",bus);run_test("apb_test");end
endmodule

uvm/apb_uvm_pkg.sv:
package apb_uvm_pkg;
 import uvm_pkg::*;
 `include "uvm_macros.svh"
 class apb_item extends uvm_sequence_item;
  rand bit write;
  rand bit [15:0] addr;
  rand bit [31:0] data;
  bit [31:0] rdata;
  bit error;
  `uvm_object_utils_begin(apb_item)
   `uvm_field_int(write,UVM_DEFAULT)
   `uvm_field_int(addr,UVM_DEFAULT)
   `uvm_field_int(data,UVM_DEFAULT)
   `uvm_field_int(rdata,UVM_DEFAULT)
   `uvm_field_int(error,UVM_DEFAULT)
  `uvm_object_utils_end
  function new(string name="apb_item");super.new(name);endfunction
 endclass
 class apb_seq extends uvm_sequence #(apb_item);
  `uvm_object_utils(apb_seq)
  function new(string name="apb_seq");super.new(name);endfunction
  task body(); apb_item tr;
   for(int i=0;i<4;i++) begin
    tr=apb_item::type_id::create("tr");start_item(tr);
    tr.write=(i%2==0);tr.addr=16'h1000;tr.data=32'hABCD;
    finish_item(tr);
   end
  endtask
 endclass
 class apb_sequencer extends uvm_sequencer #(apb_item);
  `uvm_component_utils(apb_sequencer)
  function new(string n,uvm_component p);super.new(n,p);endfunction
 endclass
 class apb_driver extends uvm_driver #(apb_item);
  `uvm_component_utils(apb_driver)
  virtual apb_if vif;
  function new(string n,uvm_component p);super.new(n,p);endfunction
  function void build_phase(uvm_phase phase);super.build_phase(phase);if(!uvm_config_db#(virtual apb_if)::get(this,"","vif",vif)) `uvm_fatal("NOVIF","No APB vif");endfunction
  task run_phase(uvm_phase phase);apb_item tr;
   forever begin
    seq_item_port.get_next_item(tr);
    @(negedge vif.PCLK);vif.PADDR=tr.addr;vif.PWDATA=tr.data;vif.PWRITE=tr.write;vif.PSEL=1;vif.PENABLE=0;
    @(negedge vif.PCLK);vif.PENABLE=1;
    do @(posedge vif.PCLK); while(!vif.PREADY);
    @(negedge vif.PCLK);vif.PSEL=0;vif.PENABLE=0;
    seq_item_port.item_done();
   end
  endtask
 endclass
 class apb_monitor extends uvm_monitor;
  `uvm_component_utils(apb_monitor)
  virtual apb_if vif;
  uvm_analysis_port #(apb_item) ap;
  function new(string n,uvm_component p);super.new(n,p);ap=new("ap",this);endfunction
  function void build_phase(uvm_phase phase);super.build_phase(phase);if(!uvm_config_db#(virtual apb_if)::get(this,"","vif",vif)) `uvm_fatal("NOVIF","No APB vif");endfunction
  task run_phase(uvm_phase phase);apb_item tr;
   forever begin
    @(posedge vif.PCLK);
    if(vif.PRESETn && vif.PSEL && vif.PENABLE && vif.PREADY) begin
     tr=apb_item::type_id::create("observed");tr.write=vif.PWRITE;tr.addr=vif.PADDR;tr.data=vif.PWDATA;tr.rdata=vif.PRDATA;tr.error=vif.PSLVERR;
     $display("DVFLOW|MONITOR|%0t|%0h|%0d|%0h|%0h|%0d",$time,tr.addr,tr.write,tr.data,tr.rdata,tr.error);
     ap.write(tr);
    end
   end
  endtask
 endclass
 class apb_agent extends uvm_agent;
  `uvm_component_utils(apb_agent)
  apb_driver driver;apb_monitor monitor;apb_sequencer sequencer;
  function new(string n,uvm_component p);super.new(n,p);endfunction
  function void build_phase(uvm_phase phase);super.build_phase(phase);driver=apb_driver::type_id::create("driver",this);monitor=apb_monitor::type_id::create("monitor",this);sequencer=apb_sequencer::type_id::create("sequencer",this);endfunction
  function void connect_phase(uvm_phase phase);driver.seq_item_port.connect(sequencer.seq_item_export);endfunction
 endclass
 class apb_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(apb_scoreboard)
  uvm_analysis_imp #(apb_item,apb_scoreboard) analysis_export;
  bit [31:0] expected[4];
  function new(string n,uvm_component p);super.new(n,p);analysis_export=new("analysis_export",this);endfunction
  function void write(apb_item tr);
   if(tr.error) begin `uvm_warning("APBERR","Slave returned PSLVERR");return;end
   if(tr.addr<16'h1000 || tr.addr>16'h100c || tr.addr[1:0]!=0) begin `uvm_error("ADDR","Unexpected address");return;end
   if(tr.write) expected[tr.addr[3:2]]=tr.data;
   else if(expected[tr.addr[3:2]]!==tr.rdata) `uvm_error("MISMATCH",$sformatf("expected %h actual %h",expected[tr.addr[3:2]],tr.rdata))
   else `uvm_info("PASS",$sformatf("Read %h matched",tr.rdata),UVM_LOW)
  endfunction
 endclass
 class apb_env extends uvm_env;
  `uvm_component_utils(apb_env)
  apb_agent agent;apb_scoreboard scoreboard;
  function new(string n,uvm_component p);super.new(n,p);endfunction
  function void build_phase(uvm_phase phase);super.build_phase(phase);agent=apb_agent::type_id::create("agent",this);scoreboard=apb_scoreboard::type_id::create("scoreboard",this);endfunction
  function void connect_phase(uvm_phase phase);agent.monitor.ap.connect(scoreboard.analysis_export);endfunction
 endclass
 class apb_test extends uvm_test;
  `uvm_component_utils(apb_test)
  apb_env env;
  function new(string n,uvm_component p);super.new(n,p);endfunction
  function void build_phase(uvm_phase phase);super.build_phase(phase);env=apb_env::type_id::create("env",this);endfunction
  task run_phase(uvm_phase phase);apb_seq seq;phase.raise_objection(this);seq=apb_seq::type_id::create("seq");seq.start(env.agent.sequencer);#100;phase.drop_objection(this);endtask
 endclass
endpackage

